<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateAttributes;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateFilter;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateCursor;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateReadGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateSlide;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateReadGateway $readGateway,
        private readonly TemplateWriteGateway $writeGateway,
        private readonly TenantVisibilityService $tenantVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(Template $content): TemplateAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(Template $content): TemplateAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(TemplateAttributes $attributes, ?Template $original = null): TemplateAttributes
    {
        $this->logDebug("Copy with fixed for Template");
        $span = $this->startSpan("Copy with fixed for  Template");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new TemplatePresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(TemplateAttributes $attributes, ?Template $original = null): TemplateAttributes
    {
        $this->logDebug("Copy with hidden for Template");
        $span = $this->startSpan("Copy with hidden for  Template");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|TemplateRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Template");
        $span = $this->startSpan("Check visibility of an iterator for  Template");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new TemplateRef($value));
            } elseif ($value instanceof TemplateRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new TemplateFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(TemplateFilter $filter, ?TemplateCursor $cursor = null): TemplateSlide
    {
        $this->logDebug("List visibles for Template");
        $span = $this->startSpan("List visibles for  Template");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (Template $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(TemplateFilter $filter): int
    {
        $this->logDebug("Count visibles for Template");
        $span = $this->startSpan("Count visibles for  Template");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(TemplateFilter $filter, ?TemplateCursor $cursor = null): TemplateSlide
    {
        $this->logDebug("List visibles for update for Template");
        $span = $this->startSpan("List visibles for update for  Template");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (Template $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(TemplateFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Template");
        $span = $this->startSpan("Count visibles for update for  Template");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(TemplateRef $ref): ?Template
    {
        $this->logDebug("Retrieve visible for Template");
        $span = $this->startSpan("Retrieve visible for  Template");
        try {
            $filter = new TemplateFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(TemplateRef $ref): ?Template
    {
        $this->logDebug("Retrieve visible for update for Template");
        $span = $this->startSpan("Retrieve visible for update for  Template");
        try {
            $filter = new TemplateFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?TemplateRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Template");
        $span = $this->startSpan("Check fields for fix for Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateCollectNonEditableFields(Template::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?TemplateRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Template");
        $span = $this->startSpan("Check fields to hide for  Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(TemplateAttributes $attributes): TemplateAttributes
    {
        $this->logDebug("Check visibility of parent references for Template");
        $span = $this->startSpan("Check visibility of parent references for  Template");
        try {
            $tenant = $attributes->getTenant();
            if (null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant)) {
                throw new NotFoundException("Unknown Tenant " . ($tenant->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(TemplateFilter $filter): TemplateFilter
    {
        $this->logDebug("Compose visibility filter for Template");
        $span = $this->startSpan("Compose visibility filter for  Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateRestrictFilterToVisibility($filter));
            return $result->templateFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(Template $value): bool
    {
        $this->logDebug("Check if item is visible for Template");
        $span = $this->startSpan("Check if item is visible for  Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(Template $content, bool $inlist): TemplateAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Template");
        $span = $this->startSpan("Prepare hydration to visible data for Template");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new TemplateEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
